const fs=require('node:fs');
const crypto=require('node:crypto');
const {pageText,contentHtml,linksFromHtml,stripEmbeddedInstructions,extractPdfBufferText,fetchOfficialDocument}=require('../lib/community-ingest');
const records=require('../data/community-full-url-audit.json').records.filter(x=>['review-required','unavailable-recheck'].includes(x.disposition)&&!x.categoryIds.some(c=>['property-changes','utilities-support'].includes(c)));
async function one(r){try{let text,links=[],documentFingerprint='',retrievedUrl=r.sourceUrl; if(r.kind==='document'){const bytes=await fetchOfficialDocument(r.sourceUrl);documentFingerprint=crypto.createHash('sha256').update(bytes).digest('hex');text=await extractPdfBufferText(bytes);}else{const res=await fetch(r.sourceUrl,{signal:AbortSignal.timeout(45000)});if(!res.ok)throw new Error('HTTP '+res.status);retrievedUrl=res.url;const html=await res.text();text=stripEmbeddedInstructions(pageText(html));links=linksFromHtml(contentHtml(html),res.url);}return {...r,checkedAt:new Date().toISOString(),retrievedUrl,fullText:text,links,contentHash:crypto.createHash('sha256').update(text).digest('hex'),hashScheme:'page-text-v1',documentFingerprint};}catch(e){return {...r,checkedAt:new Date().toISOString(),error:e.message};}}
(async()=>{const out=[];for(let i=0;i<records.length;i+=5){out.push(...await Promise.all(records.slice(i,i+5).map(one)));process.stdout.write(`${out.length}/${records.length}\n`);}fs.mkdirSync('artifacts/source-review-2026-09-14',{recursive:true});fs.writeFileSync('artifacts/source-review-2026-09-14/operations-retrieval.json',JSON.stringify(out,null,2)+'\n');console.log(out.filter(x=>x.error).map(x=>({url:x.sourceUrl,error:x.error})));})();
